cd /workspace && python3 -c "
import resource, os
for kind, lim in [(resource.RLIMIT_AS,(512*1024**2,)*2),(resource.RLIMIT_CPU,(120,121)),(resource.RLIMIT_NOFILE,(64,64)),(resource.RLIMIT_NPROC,(32,32)),(resource.RLIMIT_FSIZE,(64*1024**2,)*2),(resource.RLIMIT_CORE,(0,0))]:
    name=resource.getrlimit(kind)
    try:
        resource.setrlimit(kind, lim)
        print('ok', kind, name, '->', lim)
    except Exception as e:
        print('FAIL', kind, name, lim, e)
"
